CREATE FUNCTION s0_row_metadata_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE actor integer; why text; archiving boolean;
BEGIN
 IF TG_OP IN ('DELETE','TRUNCATE') THEN RAISE EXCEPTION 'Hard deletion is forbidden; archive the business row with a reason'; END IF;
 actor:=NULLIF(current_setting('mehta.actor_id',true),'')::integer;
 why:=NULLIF(trim(current_setting('mehta.audit_reason',true)),'');
 IF TG_OP='INSERT' THEN
  IF NEW.row_metadata_version<>1 THEN RAISE EXCEPTION 'New rows require current provenance metadata'; END IF;
  NEW.created_by:=coalesce(NEW.created_by,actor,NEW.updated_by);
  IF NEW.created_by IS NULL THEN RAISE EXCEPTION 'An actual creator is required for a new business row'; END IF;
  IF actor IS NOT NULL AND NEW.created_by<>actor THEN RAISE EXCEPTION 'Creator must match the audit actor'; END IF;
  NEW.updated_by:=coalesce(actor,NEW.updated_by,NEW.created_by);
  NEW.created_at:=coalesce(NEW.created_at,clock_timestamp());
  NEW.updated_at:=coalesce(NEW.updated_at,NEW.created_at);
  archiving:=NEW.is_deleted OR to_jsonb(NEW)->>'status'='ARCHIVED';
 ELSE
  IF NEW.created_by IS DISTINCT FROM OLD.created_by OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN RAISE EXCEPTION 'Creation provenance is immutable, including unknown legacy provenance'; END IF;
  IF NEW.row_metadata_version IS DISTINCT FROM OLD.row_metadata_version THEN RAISE EXCEPTION 'Row metadata version is managed by the database'; END IF;
  NEW.updated_by:=coalesce(actor,NEW.updated_by);
  IF NEW.updated_by IS NULL THEN RAISE EXCEPTION 'An actual updater is required for this business change'; END IF;
  NEW.updated_at:=clock_timestamp();
  archiving:=(NEW.is_deleted AND NOT OLD.is_deleted) OR (to_jsonb(NEW)->>'status'='ARCHIVED' AND to_jsonb(OLD)->>'status' IS DISTINCT FROM 'ARCHIVED');
  IF OLD.is_deleted AND NOT NEW.is_deleted AND (actor IS NULL OR length(coalesce(why,''))<3) THEN RAISE EXCEPTION 'An audit actor and new reason are required to restore an archived row'; END IF;
 END IF;
 IF archiving THEN
  actor:=coalesce(actor,NEW.updated_by,NEW.deleted_by);
  why:=coalesce(why,NULLIF(trim(NEW.delete_reason),''));
  IF actor IS NULL OR length(coalesce(why,''))<3 THEN RAISE EXCEPTION 'An actual actor and reason are required before archiving'; END IF;
  NEW.is_deleted:=true;NEW.deleted_by:=actor;NEW.delete_reason:=why;
  NEW.deleted_at:=clock_timestamp();NEW.row_metadata_version:=1;
 END IF;
 RETURN NEW;
END $$;

CREATE FUNCTION s0_row_metadata_audit() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE current_meta jsonb; previous_meta jsonb; key_meta jsonb; why text;
BEGIN
 SELECT jsonb_object_agg(key,value) INTO current_meta FROM jsonb_each(to_jsonb(NEW))
 WHERE key IN ('created_at','updated_at','created_by','updated_by','is_deleted','deleted_at','deleted_by','delete_reason','row_metadata_version');
 IF TG_OP='UPDATE' THEN
  SELECT jsonb_object_agg(key,value) INTO previous_meta FROM jsonb_each(to_jsonb(OLD))
  WHERE key IN ('created_at','updated_at','created_by','updated_by','is_deleted','deleted_at','deleted_by','delete_reason','row_metadata_version');
 END IF;
 SELECT jsonb_object_agg(key,value) INTO key_meta FROM jsonb_each(to_jsonb(NEW)) WHERE key=ANY(string_to_array(TG_ARGV[0],','));
 why:=coalesce(NULLIF(trim(current_setting('mehta.audit_reason',true)),''),CASE WHEN NEW.is_deleted THEN NEW.delete_reason END,CASE WHEN TG_OP='INSERT' THEN 'Business row created' ELSE 'Business row metadata updated' END);
 INSERT INTO audit_logs(user_id,entity,record_id,action,old_value,new_value,reason)
 VALUES(NEW.updated_by,'ROW_METADATA',TG_TABLE_NAME||':'||key_meta::text,TG_OP,previous_meta::text,current_meta::text,why);
 RETURN NEW;
END $$;

